from pathlib import Path
import json,base64,gzip,hashlib
R=Path.cwd()
PAYLOAD = ''
for item in json.loads(gzip.decompress(base64.b64decode(PAYLOAD))):
 p=R/item['path'];s=p.read_text() if p.exists() else ''
 assert hashlib.sha256(s.encode()).hexdigest()==item['before'],item['path']
 for start,end,value in sorted(item['ops'],reverse=True):s=s[:start]+value+s[end:]
 assert hashlib.sha256(s.encode()).hexdigest()==item['after'],item['path']
 p.parent.mkdir(parents=True,exist_ok=True);p.write_text(s)
